const cleanMarkdown = (markdown: string): string => {
    // Turndown can indent an entire block. Remove only common leading spaces so
    // nested lists and the contents of code blocks keep their relative indentation.
    const lines = markdown.split('\n');
    const indents = lines.filter((line) => line.trim()).map((line) => line.match(/^ */)?.[0].length || 0);
    const commonIndent = Math.min(...indents);
    return lines
        .map((line) => {
            const unindented = line.slice(Math.min(commonIndent, line.match(/^ */)?.[0].length || 0));
            const listItem = /^( *)([-+*]|\d+\.) +(.+)$/.exec(unindented);
            if (listItem) {
                // Turndown adds four spaces to lines after a nested list, including
                // the next sibling item. Keep the remaining indent for list depth.
                const indent = Math.max(0, listItem[1].length - 4);
                return `${' '.repeat(indent)}${listItem[2]} ${listItem[3]}`;
            }
            return unindented;
        })
        .join('\n');
};

