+export const fixNestedLists = (dom: Document): Document => {
+    dom.querySelectorAll('ul, ol').forEach((list) => {
+        Array.from(list.children).forEach((child) => {
+            if (child.tagName.toLowerCase() !== 'ul' && child.tagName.toLowerCase() !== 'ol') {
+                return;
+            }
+
+            let container = child.previousElementSibling;
+            if (container?.tagName.toLowerCase() !== 'li') {
+                container = dom.createElement('li');
